using Health_Care_System.BLL.Interfaces; using Health_Care_System.Data; using Health_Care_System.Entities; using Microsoft.EntityFrameworkCore;
namespace Health_Care_System.BLL.Implementations;
public class GenericRepository<TEntity>:IGenericRepository<TEntity> where TEntity:BaseEntity { protected readonly AppDbContext Context; protected readonly DbSet<TEntity> DbSet; public GenericRepository(AppDbContext context){Context=context;DbSet=context.Set<TEntity>();} public async Task CreateAsync(TEntity entity)=>await DbSet.AddAsync(entity); public void Update(TEntity entity)=>DbSet.Update(entity); public void Delete(TEntity entity)=>DbSet.Remove(entity); public async Task<TEntity?> GetAsync(int id)=>await DbSet.FindAsync(id); public async Task<IEnumerable<TEntity>> GetAllAsync()=>await DbSet.AsNoTracking().ToListAsync(); public async Task<IEnumerable<TEntity>> SearchAsync(string value)=>await DbSet.AsNoTracking().Where(x=>EF.Property<string>(x,"Name").Contains(value)).ToListAsync(); }
